import{_ as i,o as e,c as a,an as t}from"./chunks/framework.Ce68GR3m.js";const c=JSON.parse('{"title":"Kernel Fusion","description":"","frontmatter":{},"headers":[],"relativePath":"perf/kernel_fusion.md","filePath":"perf/kernel_fusion.md","lastUpdated":null}'),n={name:"perf/kernel_fusion.md"};function l(h,s,p,r,o,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="Kernel-Fusion" tabindex="-1">Kernel Fusion <a class="header-anchor" href="#Kernel-Fusion" aria-label="Permalink to &quot;Kernel Fusion {#Kernel-Fusion}&quot;">​</a></h1><p>When CUDA is available cuNumeric.jl provides several methods to fuse operations into a single CUDA kernel. This can greatly improve performance and should be used whenever possible.</p><h2 id="Automatic-Broadcast-Fusion" tabindex="-1">Automatic Broadcast Fusion <a class="header-anchor" href="#Automatic-Broadcast-Fusion" aria-label="Permalink to &quot;Automatic Broadcast Fusion {#Automatic-Broadcast-Fusion}&quot;">​</a></h2><p>Eligible broadcast expressions (i.e., <code>z .= cos.(x) .+ y</code>) are automatically fused into a single CUDA kernel.</p><p>We reccomend using Julia&#39;s <code>@.</code> macro to ensure the entire expression gets fused. A missing dot can result in poor performance!</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A missing dot on unary negation changes the expression and can prevent fusion.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> .-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prefer this form.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c</span></span></code></pre></div><p>Automatic kernel fusion requires that:</p><ol><li>Arrays have the same shape. Shape-mismatched broadcasts such as <code>matrix .+ vector</code> use the unfused path.</li><li>Expressions have at least two broadcast operations. Expressions like <code>y .= cos.(x)</code> with a single operation are unfused to reduce compilation overhead. This setting can be modified by calling <code>CNPreferences.set_broadcast_fusion_min_ops!(x::Int)</code> before launching cuNumeric. The default is <code>x = 2</code>.</li><li>A CUDA device is available.</li></ol><p>Broadcast fusion can be disabled or re-enabled with CNPreferences as well:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CNPreferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">enable_broadcast_fusion!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CNPreferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">disable_broadcast_fusion!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>For more information on setting preferences see the CNPreferences <a href="./../api_preferences">CNPreferences documentation</a>.</p><h2 id="Fuse-Multiple-Expressions-with-@accelerate" tabindex="-1">Fuse Multiple Expressions with <code>@accelerate</code> <a class="header-anchor" href="#Fuse-Multiple-Expressions-with-@accelerate" aria-label="Permalink to &quot;Fuse Multiple Expressions with \`@accelerate\` {#Fuse-Multiple-Expressions-with-@accelerate}&quot;">​</a></h2><p>One function of the <code>@accelerate</code> macro is to analyze code and find temporary variables which can be elided via kernel fusion. In the example below <code>tmp</code> is unused outside of the <code>update!</code> function, so <code>@accelerate</code> will merge the two lines together.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@accelerate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> update!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result, A, B, C)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> A </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    result .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0f0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>The equivalent code is <code>result .= @. (A + B) * C + 1.0f0</code>. The rewrite is conservative: the producer must have one use, no intervening statement may invalidate its inputs, and the normal fusion requirements still apply.</p><p>This pattern requires the intermediate object to be temporary, and not pre-allocated. For example, if <code>tmp</code> was externally managed storage whose values were modified with <code>.=</code>, <code>@accelerate</code> would not be able to combine the expressions. For example, the following code would remain as two kernels.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tmp .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> A </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0f0</span></span></code></pre></div><p>More details on <code>@accelerate</code> can be found in the <a href="./reduce_allocations">memory management</a> docs.</p><h2 id="Other" tabindex="-1">Other <a class="header-anchor" href="#Other" aria-label="Permalink to &quot;Other {#Other}&quot;">​</a></h2><p>To inspect the kernels emitted by broadcast fusion see these docs: <a href="/cuNumeric.jl/previews/PR191/debugging#inspect-fused-broadcasts-with-bcast_fusion_debug"><code>BCAST_FUSION_DEBUG</code></a>.</p>`,20)])])}const u=i(n,[["render",l]]);export{c as __pageData,u as default};
